def solve_grid(grid):
    rows = len(grid)
    cols = len(grid[0]) if rows > 0 else 0

    # Find 4-region boundaries
    first_4_row = None
    last_4_row = None
    for r in range(rows):
        if any(grid[r][c] == 4 for c in range(cols)):
            if first_4_row is None:
                first_4_row = r
            last_4_row = r

    # Find 6-region boundaries
    first_6_row = None
    last_6_row = None
    for r in range(rows):
        if any(grid[r][c] == 6 for c in range(cols)):
            if first_6_row is None:
                first_6_row = r
            last_6_row = r

    if first_4_row is None or first_6_row is None:
        return [[0]*cols for _ in range(rows)]

    num_6_rows = last_6_row - first_6_row + 1  # Number of rows in 6-shape

    output = [[0]*cols for _ in range(rows)]

    # Copy 4-region as-is
    for r in range(first_4_row, last_4_row + 1):
        for c in range(cols):
            output[r][c] = grid[r][c]

    # Mirror num_6_rows worth of 4-regions downward
    # Range is [last_4_row+1, ..., last_4_row + num_6_rows] inclusive
    # So stop is last_4_row + 1 + num_6_rows
    for r in range(last_4_row + 1, last_4_row + 1 + num_6_rows):
        src_r = last_4_row - (r - (last_4_row + 1))
        if src_r >= first_4_row:
            for c in range(cols):
                output[r][c] = grid[src_r][c]

    return output

